// Credit estimates are supplied independently of API monetary results.
const creditsApiFixture=structuredClone(officialFixture);
const creditRates={unit:'credits_per_million_tokens',uncachedInput:'25',cachedInput:'2.5',output:'150',rateDate:'2026-09-30',historical:false,billingBasis:'purchased_credits',sourceUrl:'https://learn.chatgpt.com/docs/pricing'};
const syntheticCredit=(credits,unpricedTokens=0)=>({credits,status:credits===null?'unavailable':unpricedTokens?'partial':'estimated',unpricedTokens,note:'合成 Credit 估算说明',standardRates:null,rateDate:'2026-09-30',historical:false,estimateBasis:'standard'});
for(const owner of [creditsApiFixture.turns[0],creditsApiFixture.periods.today,creditsApiFixture.periods.subscription]) {
  (owner.pricing||owner).creditEstimate=syntheticCredit('11.123457',600000);
  owner.models.forEach((row,i)=>{row.creditEstimate=syntheticCredit(i===0?'9.123456':i===1?'2.000001':null,i===2?600000:0);if(row.model)row.creditEstimate.standardRates=structuredClone(creditRates);});
}
